// convertNotificationToGraphQL converts a service notification to GraphQL type
func (r *Resolver) convertNotificationToGraphQL(ctx context.Context, notif *models.Notification) *model.Notification {
	if notif == nil {
		return nil
	}

	account := r.loadNotificationActor(ctx, notif)
	if account == nil {
		account = r.fallbackNotificationActor(notif)
	}

	status := r.loadNotificationStatus(ctx, notif)

	return &model.Notification{
		ID:            notif.ID,
		Type:          notif.Type,
		Account:       account,
		Status:        status,
		Communication: communicationNotificationFromData(notif.Type, notif.CreatedAt, notif.Data),
		Read:          notif.IsRead,
		CreatedAt:     model.Time(notif.CreatedAt),
	}
}

