func (r *Resolver) convertScheduledStatusToGraphQL(ctx context.Context, ss *storage.ScheduledStatus) *model.ScheduledStatus {
	if ss == nil {
		return nil
	}

	visibility := model.VisibilityPublic
	switch strings.ToLower(ss.Visibility) {
	case VisibilityUnlisted:
		visibility = model.VisibilityUnlisted
	case EventTypeFollowers, VisibilityPrivate:
		visibility = model.VisibilityFollowers
	case TimelineTypeDirect:
		visibility = model.VisibilityDirect
	}

	params := &model.StatusParams{
		Text:        ss.Status,
		Visibility:  visibility,
		Sensitive:   ss.Sensitive,
		SpoilerText: &ss.SpoilerText,
		InReplyToID: &ss.InReplyToID,
		Language:    &ss.Language,
	}

	// Handle poll if present
	if ss.Poll != nil {
		// Validate poll parameters using centralized validation
		if err := common.ValidatePollParams(ss.Poll); err != nil {
			// Log error but continue - this is a conversion function
			r.Logger.Warn("invalid poll parameters in scheduled status", zap.Error(err))
		}

		// Poll is stored as map[string]any, need to extract fields
		pollParams := &model.PollParams{}
		if options, ok := ss.Poll["options"].([]string); ok {
			pollParams.Options = options
		}
		if expiresIn, ok := ss.Poll["expires_in"].(int); ok {
			pollParams.ExpiresIn = expiresIn
		}
		if multiple, ok := ss.Poll["multiple"].(bool); ok {
			pollParams.Multiple = &multiple
		}
		if hideTotals, ok := ss.Poll["hide_totals"].(bool); ok {
			pollParams.HideTotals = &hideTotals
		}
		params.Poll = pollParams
	}

	mediaAttachments := make([]*model.Media, 0)
	for _, mediaID := range ss.MediaIDs {
		result, err := r.Registry.Media().GetMedia(ctx, &media.GetMediaQuery{
			MediaID:  mediaID,
			ViewerID: getUsernameFromContext(ctx),
		})
		if err == nil && result != nil {
			mediaAttachments = append(mediaAttachments, r.convertMediaToGraphQL(result))
		}
	}

	return &model.ScheduledStatus{
		ID:               ss.ID,
		ScheduledAt:      model.Time(ss.ScheduledAt),
		Params:           params,
		MediaAttachments: mediaAttachments,
		CreatedAt:        model.Time(ss.CreatedAt),
	}
}

func (r *Resolver) convertRelationshipToGraphQL(rel *relationships.RelationshipData) *model.Relationship {
	if rel == nil {
		return &model.Relationship{
			ID:                  "",
			Following:           false,
			FollowedBy:          false,
			Blocking:            false,
			BlockedBy:           false,
			Muting:              false,
			MutingNotifications: false,
			Requested:           false,
			DomainBlocking:      false,
			ShowingReblogs:      true,
			Notifying:           false,
		}
	}

	return &model.Relationship{
		ID:                  rel.ID,
		Following:           rel.Following,
		FollowedBy:          rel.FollowedBy,
		Blocking:            rel.Blocking,
		BlockedBy:           rel.BlockedBy,
		Muting:              rel.Muting,
		MutingNotifications: rel.MutingNotifications,
		Requested:           rel.Requested,
		DomainBlocking:      rel.DomainBlocking,
		ShowingReblogs:      rel.ShowingReblogs,
		Notifying:           rel.Notifying,
		Languages:           rel.Languages,
		Note:                &rel.Note,
	}
}

func (r *Resolver) convertAccountToActor(account *storage.Account) *activitypub.Actor {
	if account == nil {
		return nil
	}

	username := ""
	if account.User != nil {
		username = account.User.Username
	}

	baseURL := ""
	if r.Config != nil {
		baseURL = r.Config.BaseURL()
	}

	return activitypubutil.BuildLocalActor(username, baseURL, account.User, account.Actor)
}

func (r *Resolver) convertNoteToObject(ctx context.Context, note *activitypub.Note) *model.Object {
	if note == nil {
		return nil
	}

	objectType := model.ObjectTypeNote
	visibility := model.VisibilityPublic

	// Determine visibility from note properties
	if note.Visibility != "" {
		switch note.Visibility {
		case VisibilityUnlisted:
			visibility = model.VisibilityUnlisted
		case VisibilityPrivate, EventTypeFollowers:
			visibility = model.VisibilityFollowers
		case TimelineTypeDirect:
			visibility = model.VisibilityDirect
		}
	}

	// Get actor information
	var actor *activitypub.Actor
	if note.AttributedTo != "" {
		// Extract username from actor ID
		parts := strings.Split(note.AttributedTo, "/")
		username := parts[len(parts)-1]
		if username != "" {
			result, err := r.Registry.Accounts().GetAccount(ctx, username)
			if err == nil && result != nil {
				actor = r.convertAccountToActor(result)
			}
		}
	}

	// Convert attachments
	attachments := make([]*activitypub.Attachment, len(note.Attachment))
	for i, att := range note.Attachment {
		attachments[i] = &att
	}

	// Convert tags
	tags := make([]*activitypub.Tag, len(note.Tag))
	for i, tag := range note.Tag {
		tags[i] = &tag
	}

	// Create inReplyTo object if exists
	var inReplyToObj *model.Object
	if note.InReplyTo != "" {
		// Fetch the actual reply object using Notes service
		viewerUsername := getUsernameFromContext(ctx)
		replyNote, err := r.Registry.Notes().GetNoteWithViewer(ctx, &notes.GetNoteQuery{
			StatusID: note.InReplyTo,
			ViewerID: viewerUsername,
		})
		if err != nil {
			r.Logger.Debug("failed to fetch reply object",
				zap.String("reply_id", note.InReplyTo),
				zap.Error(err))
			// Continue without reply object instead of failing
			inReplyToObj = nil
		} else if replyNote != nil {
			// Convert the reply status directly to model.Object
			inReplyToObj = r.convertStatusToObject(ctx, replyNote)
		}
	}

	createdAt := firstNonZeroTime(note.Published, note.Updated)
	if createdAt == nil {
		now := time.Now().UTC()
		createdAt = &now
	}
	updatedAt := firstNonZeroTime(note.Updated, note.Published)
	if updatedAt == nil {
		clone := createdAt.UTC()
		updatedAt = &clone
	}

	return &model.Object{
		ID:             note.ID,
		Type:           objectType,
		Actor:          actor,
		Content:        note.Content,
		ContentMap:     r.extractContentMaps(note.Content), // Enhanced: extract content maps with language detection
		InReplyTo:      inReplyToObj,
		Visibility:     visibility,
		Sensitive:      note.Sensitive,
		SpoilerText:    &note.Summary, // Map Summary to SpoilerText
		Attachments:    attachments,
		Tags:           tags,
		Mentions:       r.extractMentionsFromNote(note), // Enhanced: extract mentions from note tags
		CreatedAt:      model.Time(*createdAt),
		UpdatedAt:      model.Time(*updatedAt),
		RepliesCount:   r.getReplyCount(ctx, note.ID), // Use efficient count method
		LikesCount:     0,
		SharesCount:    0,
		ContentHash:    contentHashForObjectID(note.ID),
		EstimatedCost:  0,
		CommunityNotes: r.getCommunityNotesForObject(ctx, note.ID),
		AgentAttribution: func() *activitypub.AgentPostAttribution {
			if note == nil {
				return nil
			}
			return note.AgentAttribution
		}(),
	}
}

// getCommunityNotesForObject efficiently gets community notes for an object
func (r *Resolver) getCommunityNotesForObject(ctx context.Context, objectID string) []*model.CommunityNote {
	notes, err := r.Storage.CommunityNote().GetVisibleCommunityNotes(ctx, objectID)
	if err != nil {
		r.Logger.Error("failed to get community notes", zap.String("objectID", objectID), zap.Error(err))
		return []*model.CommunityNote{} // Return empty on error rather than failing the request
	}

	// Convert storage.CommunityNote to model.CommunityNote
	result := make([]*model.CommunityNote, len(notes))
	for i, note := range notes {
		// Get author information - would typically fetch from Actor repository
		var author *activitypub.Actor
		if note.AuthorID != "" {
			// For now, create a minimal actor - in production you'd fetch from storage
			author = &activitypub.Actor{
				BaseObject: activitypub.BaseObject{
					ID:   note.AuthorID,
					Type: "Person",
				},
				PreferredUsername: deriveUsernameFromIRI(note.AuthorID), // Simplified - would extract username properly
			}
		}

		result[i] = &model.CommunityNote{
			ID:         note.ID,
			Author:     author,
			Content:    note.Content,
			Helpful:    note.HelpfulVotes,
			NotHelpful: note.NotHelpfulVotes,
			CreatedAt:  model.Time(note.CreatedAt),
		}
	}
	return result
}

// getReplyCount efficiently gets the reply count for a note/status
func (r *Resolver) getReplyCount(ctx context.Context, noteID string) int {
	count, err := r.Storage.Status().CountReplies(ctx, noteID)
	if err != nil {
		r.Logger.Error("failed to get reply count", zap.String("noteID", noteID), zap.Error(err))
		return 0 // Return 0 on error rather than failing the request
	}
	return count
}

// extractContentMaps creates ContentMap entries for content with language detection
func (r *Resolver) extractContentMaps(content string) []*model.ContentMap {
	if err := common.ValidateRequiredParam("content", content); err != nil {
		return []*model.ContentMap{}
	}

	// Detect language using simple heuristics (similar to activity processor)
	language := r.detectContentLanguage(content)

	return []*model.ContentMap{
		{
			Language: language,
			Content:  content,
		},
	}
}

// detectContentLanguage performs simple language detection on content
func (r *Resolver) detectContentLanguage(content string) string {
	if err := common.ValidateRequiredParam("content", content); err != nil {
		return "en" // Default to English
	}

	// Convert to lowercase for analysis
	text := strings.ToLower(content)

	// Strip HTML tags for cleaner analysis
	text = r.stripHTMLTags(text)

	// Character-based detection for non-Latin scripts
	if r.hasJapaneseCharacters(text) {
		return "ja"
	}
	if r.hasChineseCharacters(text) {
		return "zh"
	}
	if r.hasKoreanCharacters(text) {
		return "ko"
	}
	if r.hasArabicCharacters(text) {
		return "ar"
	}

	// Default to English for Latin scripts
	return "en"
}

// stripHTMLTags removes HTML tags from content
func (r *Resolver) stripHTMLTags(content string) string {
	// Simple HTML tag removal - replace with regex for production
	htmlTag := regexp.MustCompile(`<[^>]*>`)
	return htmlTag.ReplaceAllString(content, "")
}

// hasJapaneseCharacters checks for Japanese characters
func (r *Resolver) hasJapaneseCharacters(text string) bool {
	for _, r := range text {
		if (r >= 0x3040 && r <= 0x309F) || // Hiragana
			(r >= 0x30A0 && r <= 0x30FF) || // Katakana
			(r >= 0x4E00 && r <= 0x9FAF) { // CJK Ideographs (includes Kanji)
			return true
		}
	}
	return false
}

// hasChineseCharacters checks for Chinese characters
func (r *Resolver) hasChineseCharacters(text string) bool {
	for _, r := range text {
		if (r >= 0x4E00 && r <= 0x9FAF) || // CJK Ideographs
			(r >= 0x3400 && r <= 0x4DBF) { // CJK Extension A
			return true
		}
	}
	return false
}

// hasKoreanCharacters checks for Korean characters
func (r *Resolver) hasKoreanCharacters(text string) bool {
	for _, r := range text {
		if r >= 0xAC00 && r <= 0xD7AF { // Hangul Syllables
			return true
		}
	}
	return false
}

// hasArabicCharacters checks for Arabic characters
func (r *Resolver) hasArabicCharacters(text string) bool {
	for _, r := range text {
		if r >= 0x0600 && r <= 0x06FF { // Arabic
			return true
		}
	}
	return false
}

// extractMentionsFromNote extracts mention objects from ActivityPub note tags
func (r *Resolver) extractMentionsFromNote(note *activitypub.Note) []*model.Mention {
	if note == nil || len(note.Tag) == 0 {
		return []*model.Mention{}
	}

	mentions := []*model.Mention{}

	for _, tag := range note.Tag {
		if tag.Type == "Mention" && tag.Href != "" {
			// Extract username and domain from mention URL
			username, domain := r.parseMentionURL(tag.Href)
			if username != "" {
				mentions = append(mentions, &model.Mention{
					ID:       tag.Href,
					Username: username,
					Domain:   domain,
					URL:      tag.Href,
				})
			}
		}
	}

	return mentions
}

// parseMentionURL extracts username and domain from a mention URL
func (r *Resolver) parseMentionURL(url string) (username string, domain *string) {
	if err := common.ValidateRequiredParam("url", url); err != nil {
		return "", nil
	}

	// Parse the URL to extract components
	// Expected formats: https://domain.com/users/username or https://domain.com/@username
	parts := strings.Split(url, "/")
	if len(parts) < 3 {
		return "", nil
	}

	// Extract domain
	domainPart := parts[2] // e.g., "example.com"

	// Extract username (last part of URL, removing @ if present)
	usernamePart := parts[len(parts)-1]
	usernamePart = strings.TrimPrefix(usernamePart, "@")

	if err := common.ValidateRequiredParam("usernamePart", usernamePart); err != nil {
		return "", nil
	}

	// Return domain only if it's different from current instance
	var domainPtr *string
	if domainPart != "" && !strings.Contains(r.Registry.GetConfig().BaseURL, domainPart) {
		domainPtr = &domainPart
	}

	return usernamePart, domainPtr
}

var viewerBoostStateResolverFunc = loadViewerBoostState

func loadViewerBoostState(ctx context.Context, r *Resolver, viewerID, statusID string) (bool, error) {
	if r == nil || viewerID == "" || statusID == "" {
		return false, nil
	}

	notesService := r.notesService()
	if notesService == nil {
		return false, nil
	}

	return notesService.HasReblogged(ctx, viewerID, statusID)
}

func (r *Resolver) convertStatusToObject(ctx context.Context, status *models.Status) *model.Object {
	if status == nil {
		return nil
	}

	var convertLogger *zap.Logger
	if r.Logger != nil {
		convertLogger = r.Logger
		convertLogger.Info("convertStatusToObject started",
			zap.String("status_id", status.StatusID))
	}

	start := time.Now()

	var poll *model.Poll
	if status.StatusID != "" {
		poll = r.resolvePollForStatus(ctx, status)
	}

	viewerBoosted := r.viewerBoostState(ctx, status, convertLogger)
	objectType := model.ObjectTypeNote
	visibility := mapStatusVisibility(status)
	actor := r.resolveActorForStatus(ctx, status, convertLogger)
	attachments := cloneNoteAttachments(status)
	tags := cloneNoteTags(status)
	quoteURL, quoteContext := r.resolveQuoteMetadata(ctx, status)
	quoteable := determineQuoteable(status)
	mentions := r.buildMentions(status)
	inReplyTo := r.resolveInReplyToObject(ctx, status, convertLogger)
	summary := extractStatusSummary(status)

	obj := &model.Object{
		ID:               status.StatusID,
		Type:             objectType,
		Actor:            actor,
		Content:          status.Content,
		ContentMap:       r.extractContentMaps(status.Content),
		InReplyTo:        inReplyTo,
		Visibility:       visibility,
		Sensitive:        status.Sensitive,
		SpoilerText:      summary,
		Attachments:      attachments,
		Tags:             tags,
		Mentions:         mentions,
		CreatedAt:        model.Time(status.CreatedAt),
		UpdatedAt:        model.Time(status.UpdatedAt),
		Poll:             poll,
		RepliesCount:     status.ReplyCount,
		LikesCount:       status.LikeCount,
		SharesCount:      status.ReblogCount,
		CommunityNotes:   []*model.CommunityNote{},
		QuoteURL:         quoteURL,
		QuoteContext:     quoteContext,
		Quoteable:        quoteable,
		QuotePermissions: model.QuotePermissionEveryone,
		QuoteCount:       status.QuoteCount,
		Quotes: &model.QuoteConnection{
			Edges:      []*model.QuoteEdge{},
			PageInfo:   &model.PageInfo{HasNextPage: false, HasPreviousPage: false},
			TotalCount: status.QuoteCount,
		},
		ContentHash:   contentHashForObjectID(status.StatusID),
		EstimatedCost: 1,
		Boosted:       viewerBoosted,
		AgentAttribution: func() *activitypub.AgentPostAttribution {
			if status.Note == nil {
				return nil
			}
			return status.Note.AgentAttribution
		}(),
	}

	obj.RelationshipType = model.ObjectRelationshipTypeOriginal
	if status.IsReblog() {
		obj.RelationshipType = model.ObjectRelationshipTypeBoost
		obj.BoostedObject = r.resolveBoostedObject(ctx, status, convertLogger)
	}

	if convertLogger != nil {
		convertLogger.Info("convertStatusToObject finished",
			zap.String("status_id", status.StatusID),
			zap.Duration("duration", time.Since(start)),
			zap.Bool("actor_loaded", actor != nil),
			zap.Int("attachment_count", len(attachments)))
	}

	return obj
}

func (r *Resolver) resolveQuoteMetadata(ctx context.Context, status *models.Status) (*string, *activitypub.QuoteContext) {
	if status == nil || status.QuoteTargetStatusID == "" {
		return nil, nil
	}

	var (
		targetStatus *models.Status
		lookupStart  = time.Now()
		err          error
	)

	targetStatus, err = r.loadQuoteTargetStatus(ctx, status.QuoteTargetStatusID)
	if err != nil && r.Logger != nil {
		r.Logger.Warn("failed to resolve quote target",
			zap.String("status_id", status.StatusID),
			zap.String("target_status_id", status.QuoteTargetStatusID),
			zap.Duration("duration", time.Since(lookupStart)),
			zap.Error(err))
	}

	originalAuthor := status.QuoteTargetAuthorID
	originalAuthorUsername := ""
	if targetStatus != nil {
		if targetStatus.AuthorID != "" {
			originalAuthor = targetStatus.AuthorID
		} else if targetStatus.AuthorUsername != "" && originalAuthor == "" {
			originalAuthor = targetStatus.AuthorUsername
		}
		if targetStatus.AuthorUsername != "" {
			originalAuthorUsername = targetStatus.AuthorUsername
		}
	}
	if originalAuthor == "" {
		originalAuthor = status.QuoteTargetStatusID
	}
	if originalAuthorUsername == "" {
		originalAuthorUsername = extractUsernameFromActorIdentifier(originalAuthor)
	}

	quoteCount := 0
	if targetStatus != nil {
		quoteCount = targetStatus.QuoteCount
	}

	quoteURLValue := ""
	if targetStatus != nil {
		quoteURLValue = extractQuoteURLFromStatus(targetStatus)
	}
	if quoteURLValue == "" {
		quoteURLValue = status.QuoteTargetStatusID
	}

	var quoteURL *string
	if quoteURLValue != "" {
		quoteURL = &quoteURLValue
	}

	quoteAllowed := true
	withdrawn := false
	if targetStatus != nil && targetStatus.Deleted {
		withdrawn = true
		quoteAllowed = false
	}

	quoteContext := &activitypub.QuoteContext{
		OriginalNoteID:         status.QuoteTargetStatusID,
		OriginalAuthor:         originalAuthor,
		OriginalAuthorUsername: originalAuthorUsername,
		QuoteCount:             quoteCount,
		AllowWithdrawal:        true,
		QuoteAllowed:           quoteAllowed,
		Withdrawn:              withdrawn,
		OriginalStatus:         targetStatus,
	}

	if r.Logger != nil {
		url := ""
		if quoteURL != nil {
			url = *quoteURL
		}
		r.Logger.Debug("resolved quote metadata",
			zap.String("status_id", status.StatusID),
			zap.String("target_status_id", status.QuoteTargetStatusID),
			zap.String("quote_url", url),
			zap.Int("quote_count", quoteContext.QuoteCount),
			zap.Bool("quote_allowed", quoteContext.QuoteAllowed),
			zap.Bool("withdrawn", quoteContext.Withdrawn))
	}
	return quoteURL, quoteContext
}

var quoteTargetStatusLoaderFunc = LoadQuoteTargetStatus
var actorLoaderFunc = LoadActor

func (r *Resolver) loadQuoteTargetStatus(ctx context.Context, statusID string) (*models.Status, error) {
	if statusID == "" {
		return nil, nil
	}

	targetStatus, err := quoteTargetStatusLoaderFunc(ctx, statusID)
	if err == nil {
		return targetStatus, nil
	}

	// If loaders aren't available, fall back to direct Notes service lookup.
	if errors.Is(err, errLoadersNotFound) || errors.Is(err, errQuoteTargetLoaderUnavailable) {
		if r.Registry != nil && r.Registry.Notes() != nil {
			viewerUsername := getUsernameFromContext(ctx)
			return r.Registry.Notes().GetNoteWithViewer(ctx, &notes.GetNoteQuery{
				StatusID: statusID,
				ViewerID: viewerUsername,
			})
		}
		return nil, err
	}

	return nil, err
}

func extractQuoteURLFromStatus(status *models.Status) string {
	if status == nil || status.Note == nil {
		return ""
	}

	note := status.Note
	if note.ID == "" {
		return ""
	}

	return note.ID
}

func (r *Resolver) resolvePollForStatus(ctx context.Context, status *models.Status) *model.Poll {
	if r.Storage == nil || status == nil {
		return nil
	}

	pollRepo := r.Storage.Poll()
	if pollRepo == nil {
		return nil
	}

	pollRecord, err := pollRepo.GetPollByStatusID(ctx, status.StatusID)
	if err != nil {
		if !apperrors.HasCode(err, apperrors.CodeNotFound) && r.Logger != nil {
			r.Logger.Warn("failed to load poll for status",
				zap.String("status_id", status.StatusID),
				zap.Error(err))
		}
		return nil
	}

	r.trackDynamoOperation(ctx, DynamoOperationQuery, 1)

	var viewerVotes []int
	viewerUsername := getUsernameFromContext(ctx)
	if viewerUsername != "" && r.Registry != nil {
		accountResult, accountErr := r.Registry.Accounts().GetAccount(ctx, viewerUsername)
		if accountErr != nil {
			if r.Logger != nil {
				r.Logger.Debug("failed to load account while resolving poll votes",
					zap.String("username", viewerUsername),
					zap.Error(accountErr))
			}
		} else if accountResult != nil && accountResult.Actor != nil {
			if voted, votes, voteErr := pollRepo.HasUserVoted(ctx, pollRecord.ID, accountResult.Actor.ID); voteErr != nil {
				if !apperrors.HasCode(voteErr, apperrors.CodeNotFound) && r.Logger != nil {
					r.Logger.Debug("failed to resolve poll vote status",
						zap.String("poll_id", pollRecord.ID),
						zap.String("username", viewerUsername),
						zap.Error(voteErr))
				}
			} else {
				r.trackDynamoOperation(ctx, DynamoOperationQuery, 1)
				if voted {
					viewerVotes = votes
				}
			}
		}
	}

	return r.convertPollToGraphQL(pollRecord, viewerVotes)
}

func (r *Resolver) convertPollToGraphQL(poll *storage.Poll, viewerVotes []int) *model.Poll {
	if poll == nil {
		return nil
	}

	options := make([]*model.PollOption, len(poll.Options))
	totalVotes := 0
	for i, option := range poll.Options {
		votesCount := 0
		if i < len(poll.VotesCount) {
			votesCount = poll.VotesCount[i]
		}

		options[i] = &model.PollOption{
			Title:      option,
			VotesCount: votesCount,
		}
		totalVotes += votesCount
	}

	var expiresAt *model.Time
	expired := false
	if poll.ExpiresAt != nil && !poll.ExpiresAt.IsZero() {
		expires := model.Time(*poll.ExpiresAt)
		expiresAt = &expires
		expired = time.Now().After(*poll.ExpiresAt)
	}

	var ownVotes []int
	if len(viewerVotes) > 0 {
		ownVotes = make([]int, len(viewerVotes))
		copy(ownVotes, viewerVotes)
	}

	return &model.Poll{
		ID:          poll.ID,
		ExpiresAt:   expiresAt,
		Expired:     expired,
		Multiple:    poll.Multiple,
		HideTotals:  poll.HideTotals,
		VotesCount:  totalVotes,
		VotersCount: poll.VotersCount,
		Voted:       len(ownVotes) > 0,
		OwnVotes:    ownVotes,
		Options:     options,
	}
}

// Helper functions for managing conversion depth to prevent infinite recursion
type conversionDepthKey struct{}

func (r *Resolver) getConversionDepth(ctx context.Context) int {
	if depth, ok := ctx.Value(conversionDepthKey{}).(int); ok {
		return depth
	}
	return 0
}

func (r *Resolver) setConversionDepth(ctx context.Context, depth int) context.Context {
	return context.WithValue(ctx, conversionDepthKey{}, depth)
}

// ModerationFilter extension helpers for proper field resolution
// This provides a thread-safe way to extend GraphQL objects with additional fields
var moderationFilterExtensions = struct {
	sync.RWMutex
	data map[string]map[string]interface{}
}{
	data: make(map[string]map[string]interface{}),
}

func (r *Resolver) setModerationFilterExtension(_ context.Context, obj *moderation.ModerationFilter, field string, value interface{}) {
	objectID := fmt.Sprintf("%p", obj) // Use pointer address as unique identifier

	moderationFilterExtensions.Lock()
	defer moderationFilterExtensions.Unlock()

	if moderationFilterExtensions.data[objectID] == nil {
		moderationFilterExtensions.data[objectID] = make(map[string]interface{})
	}
	moderationFilterExtensions.data[objectID][field] = value
}

func (r *Resolver) convertSuggestionSource(source string) model.SuggestionSource {
	switch strings.ToUpper(source) {
	case "STAFF":
		return model.SuggestionSourceStaff
	case "PAST_INTERACTIONS":
		return model.SuggestionSourcePastInteractions
	case "SIMILAR_PROFILES":
		return model.SuggestionSourceSimilarProfiles
	default:
		return model.SuggestionSourceGlobal
	}
}

// ====================================================================
// ADVANCED FEATURE RESOLVERS
// ====================================================================

// The following resolvers implement advanced features like trust graphs,
// moderation patterns, and community analytics

// TrustGraph is the resolver for the trustGraph field.

// ModerationQueue is the resolver for the moderationQueue field.

// ExplainObject is the resolver for the explainObject field.

// convertObjectToModel converts an ActivityPub object to GraphQL model object
func (r *queryResolver) convertObjectToModel(obj any) *model.Object {
	switch o := obj.(type) {
	case *activitypub.Note:
		return &model.Object{
			ID:          o.ID,
			Type:        model.ObjectTypeNote,
			Content:     o.Content,
			CreatedAt:   model.Time(*o.Published),
			UpdatedAt:   model.Time(time.Now()),
			Sensitive:   o.Sensitive,
			Visibility:  r.mapActivityPubVisibility(o.Visibility),
			ContentHash: contentHashForObjectID(o.ID),
		}
	case *activitypub.Article:
		return &model.Object{
			ID:          o.ID,
			Type:        model.ObjectTypeArticle,
			Content:     o.Content,
			CreatedAt:   model.Time(*o.Published),
			UpdatedAt:   model.Time(time.Now()),
			ContentHash: contentHashForObjectID(o.ID),
		}
	case map[string]interface{}:
		// Handle generic ActivityPub objects stored as maps
		if objType, ok := o["type"].(string); ok {
			id := getStringFromMap(o, "id")
			modelObj := &model.Object{
				ID:          id,
				Content:     getStringFromMap(o, "content"),
				CreatedAt:   model.Time(time.Now()),
				UpdatedAt:   model.Time(time.Now()),
				ContentHash: contentHashForObjectID(id),
			}

			// Map ActivityPub types to GraphQL types
			switch strings.ToLower(objType) {
			case ContentTypeNote:
				modelObj.Type = model.ObjectTypeNote
			case ContentTypeArticle:
				modelObj.Type = model.ObjectTypeArticle
			case ContentTypeImage:
				modelObj.Type = model.ObjectTypeImage
			case ContentTypeVideo:
				modelObj.Type = model.ObjectTypeVideo
			default:
				modelObj.Type = model.ObjectTypeNote // Default fallback
			}

			return modelObj
		}
	}
	return nil
}

// calculateDetailedFederationCostBreakdown calculates detailed cost breakdown with data transfer
func (r *queryResolver) calculateDetailedFederationCostBreakdown(fedCost *models.FederationCost) *model.CostBreakdown {
	// Calculate individual service costs using the cost tracker constants and formulas

	// Data Transfer Costs - Calculate from actual ingress/egress bytes
	totalTransferBytes := fedCost.IngressBytes + fedCost.EgressBytes
	transferGB := float64(totalTransferBytes) / (1024 * 1024 * 1024)
	dataTransferCost := transferGB * 0.09 // $0.09 per GB data transfer out (S3DataTransferPerGB constant converted to dollars)

	// DynamoDB Costs - Estimate based on request count and typical read/write ratio
	// Assume 70% reads, 30% writes for federation activities
	reads := int64(float64(fedCost.RequestCount) * 0.7)
	writes := int64(float64(fedCost.RequestCount) * 0.3)
	dynamoDBCost := float64(reads*25+writes*125) / 1000000.0 // Convert from microcents to dollars

	// Lambda Costs - Estimate based on request count and typical Lambda execution
	// Assume average 200ms execution time and 512MB memory per federation request
	lambdaInvocations := fedCost.RequestCount
	avgDurationMs := int64(200)
	avgMemoryMB := int64(512)
	lambdaRequestCost := float64(lambdaInvocations*20) / 1000000.0 // Request cost using cost.LambdaRequestCost
	gbSeconds := float64(avgDurationMs*avgMemoryMB*lambdaInvocations) / (1000 * 1024)
	lambdaComputeCost := gbSeconds * 0.0000166667 // GB-second cost using cost.LambdaGBSecondCost
	lambdaCost := lambdaRequestCost + lambdaComputeCost

	// S3 Storage Costs - Minimal for federation (mostly metadata)
	// Estimate based on request count and average object sizes
	estimatedS3Gets := fedCost.RequestCount / 2                                     // Assume half are GET operations
	estimatedS3Puts := fedCost.RequestCount / 10                                    // Assume 10% are PUT operations
	s3Cost := float64(estimatedS3Gets*40/1000+estimatedS3Puts*500/1000) / 1000000.0 // Using cost tracker constants

	// Total cost calculation
	totalCost := dataTransferCost + dynamoDBCost + lambdaCost + s3Cost

	// Create detailed breakdown items
	breakdownItems := []*model.CostItem{}

	if dynamoDBCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "DynamoDB Operations",
			Count:     int(reads + writes),
			Cost:      dynamoDBCost,
		})
	}

	if lambdaCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "Lambda Execution",
			Count:     int(lambdaInvocations),
			Cost:      lambdaCost,
		})
	}

	if s3Cost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "S3 Operations",
			Count:     int(estimatedS3Gets + estimatedS3Puts),
			Cost:      s3Cost,
		})
	}

	if dataTransferCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "Data Transfer",
			Count:     int(totalTransferBytes / (1024 * 1024)), // Count in MB
			Cost:      dataTransferCost,
		})
	}

	return &model.CostBreakdown{
		Period:           model.PeriodMonth,
		TotalCost:        totalCost,
		DynamoDBCost:     dynamoDBCost,
		S3StorageCost:    s3Cost,
		LambdaCost:       lambdaCost,
		DataTransferCost: dataTransferCost,
		Breakdown:        breakdownItems,
	}
}

// mapActivityPubVisibility maps ActivityPub visibility to GraphQL visibility
func (r *queryResolver) mapActivityPubVisibility(visibility string) model.Visibility {
	switch strings.ToLower(visibility) {
	case StreamNamePublic:
		return model.VisibilityPublic
	case VisibilityUnlisted:
		return model.VisibilityUnlisted
	case VisibilityPrivate, EventTypeFollowers:
		return model.VisibilityFollowers
	case TimelineTypeDirect:
		return model.VisibilityDirect
	default:
		return model.VisibilityPublic // Default fallback
	}
}

// getStringFromMap safely extracts a string value from a map
func getStringFromMap(m map[string]interface{}, key string) string {
	if val, ok := m[key]; ok {
		if str, ok := val.(string); ok {
			return str
		}
	}
	return ""
}

// FederationStatus is the resolver for the federationStatus field.

// getDomainHealthScore retrieves the health score for a domain
func (r *queryResolver) getDomainHealthScore(ctx context.Context, federationRepo interface{}, domain string) float64 {
	defer func() {
		if rec := recover(); rec != nil {
			r.Logger.Warn("panic in getDomainHealthScore, returning default",
				zap.String("domain", domain),
				zap.Any("panic", rec))
		}
	}()

	repo, ok := federationRepo.(interface {
		GetDomainHealthScore(context.Context, string) (float64, error)
	})
	if !ok {
		r.Logger.Debug("federation repo does not support GetDomainHealthScore",
			zap.String("domain", domain))
		return 0.0
	}

	healthScore, err := repo.GetDomainHealthScore(ctx, domain)
	if err != nil {
		r.Logger.Debug("no health score found for domain",
			zap.String("domain", domain),
			zap.Error(err))
		return 0.0
	}
	return healthScore
}

// getRecentFederationMetrics retrieves recent federation metrics for a domain
func (r *queryResolver) getRecentFederationMetrics(ctx context.Context, federationRepo interface{}, domain string) []*models.FederationAnalyticsTimeSeries {
	defer func() {
		if rec := recover(); rec != nil {
			r.Logger.Warn("panic in getRecentFederationMetrics, returning empty",
				zap.String("domain", domain),
				zap.Any("panic", rec))
		}
	}()

	repo, ok := federationRepo.(interface {
		GetDetailedMetricsByPeriod(context.Context, string, time.Time, time.Time, int) ([]*models.FederationAnalyticsTimeSeries, error)
	})
	if !ok {
		r.Logger.Debug("federation repo does not support GetDetailedMetricsByPeriod",
			zap.String("domain", domain))
		return []*models.FederationAnalyticsTimeSeries{}
	}

	endTime := time.Now()
	startTime := endTime.Add(-30 * time.Minute) // Last 30 minutes of activity

	recentMetrics, err := repo.GetDetailedMetricsByPeriod(ctx, "5min", startTime, endTime, 10)
	if err != nil {
		r.Logger.Debug("no recent metrics found for domain",
			zap.String("domain", domain),
			zap.Error(err))
		return []*models.FederationAnalyticsTimeSeries{}
	}
	return recentMetrics
}

// determineReachabilityFromMetrics analyzes recent metrics to determine domain reachability
func (r *queryResolver) determineReachabilityFromMetrics(status *model.FederationStatus, recentMetrics []*models.FederationAnalyticsTimeSeries) {
	if err := common.ValidateSliceNotEmpty("recent_metrics", recentMetrics); err != nil {
		return
	}

	// Check for successful contact in recent metrics
	if r.findSuccessfulContact(status, recentMetrics) {
		return
	}

	// If no successful contact, check for any recent activity
	r.findRecentActivity(status, recentMetrics)
}

// findSuccessfulContact looks for metrics with successful contact
func (r *queryResolver) findSuccessfulContact(status *model.FederationStatus, recentMetrics []*models.FederationAnalyticsTimeSeries) bool {
	for _, metric := range recentMetrics {
		if metric.LastSuccessfulContact != nil {
			status.Reachable = true
			status.LastContact = (*model.Time)(metric.LastSuccessfulContact)
			return true
		}
	}
	return false
}

// findRecentActivity looks for any recent activity indicators
func (r *queryResolver) findRecentActivity(status *model.FederationStatus, recentMetrics []*models.FederationAnalyticsTimeSeries) {
	for _, metric := range recentMetrics {
		if metric.ActivityCount > 0 && metric.InstanceReachability > 0 {
			status.Reachable = true
			status.LastContact = (*model.Time)(&metric.Timestamp)
			return
		}
	}
}

// getInstanceInfo retrieves cached instance information for a domain
func (r *queryResolver) getInstanceInfo(ctx context.Context, federationRepo interface{}, domain string) *models.FederationInstance {
	defer func() {
		if rec := recover(); rec != nil {
			r.Logger.Warn("panic in getInstanceInfo, returning nil",
				zap.String("domain", domain),
				zap.Any("panic", rec))
		}
	}()

	repo, ok := federationRepo.(interface {
		GetInstanceInfo(context.Context, string) (*models.FederationInstance, error)
	})
	if !ok {
		r.Logger.Debug("federation repo does not support GetInstanceInfo",
			zap.String("domain", domain))
		return nil
	}

	instanceInfo, err := repo.GetInstanceInfo(ctx, domain)
	if err != nil {
		r.Logger.Debug("could not get instance information",
			zap.String("domain", domain),
			zap.Error(err))
		return nil
	}
	return instanceInfo
}

// applyInstanceInfoToStatus populates status fields from instance information
func (r *queryResolver) applyInstanceInfoToStatus(status *model.FederationStatus, instanceInfo *models.FederationInstance) {
	if instanceInfo == nil {
		return
	}

	// Set instance-level information if available
	if instanceInfo.SharedInbox != "" {
		status.SharedInbox = &instanceInfo.SharedInbox
	}
	if instanceInfo.PublicKey != "" {
		status.PublicKey = &instanceInfo.PublicKey
	}
	if instanceInfo.Software != "" {
		status.Software = &instanceInfo.Software
	}
	if instanceInfo.Version != "" {
		status.Version = &instanceInfo.Version
	}

	// Check reachability based on last seen if not already determined
	r.checkReachabilityFromLastSeen(status, instanceInfo)
}

// checkReachabilityFromLastSeen updates reachability based on instance last seen time
func (r *queryResolver) checkReachabilityFromLastSeen(status *model.FederationStatus, instanceInfo *models.FederationInstance) {
	if status.Reachable || instanceInfo.LastSeen.IsZero() {
		return
	}

	// Check if last seen was reasonably recent (within 24 hours)
	if time.Since(instanceInfo.LastSeen) < 24*time.Hour {
		status.Reachable = true
		status.LastContact = (*model.Time)(&instanceInfo.LastSeen)
	}
}

// handleMissingInstanceInfo handles the case when no instance information is available
func (r *queryResolver) handleMissingInstanceInfo(status *model.FederationStatus, instanceInfo *models.FederationInstance, domain string) {
	if instanceInfo != nil {
		return
	}

	r.Logger.Debug("no cached instance information available",
		zap.String("domain", domain))

	// For GraphQL queries, we don't want to trigger expensive network operations
	// Conservative approach: assume not reachable if no cached data
	if domain != "" {
		status.Reachable = false
	}
}

// AIAnalysis is the resolver for the aiAnalysis field.

// AIStats is the resolver for the aiStats field.

// AiCapabilities is the resolver for the aiCapabilities field.

// RequestAIAnalysis is the resolver for the requestAIAnalysis field.
func (r *mutationResolver) RequestAIAnalysis(ctx context.Context, objectID string, objectType *string, force *bool) (*model.AIAnalysisRequest, error) {
	// Require authentication
	username, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	if r.Storage == nil || r.Storage.Instance() == nil {
		return nil, ErrStorageUnavailable
	}

	exists, err := r.Storage.Instance().AIConfigExists(ctx)
	if err != nil {
		return nil, errors.Join(errors.New("failed to resolve AI configuration"), err)
	}

	if exists {
		effectiveAI, err := r.Storage.Instance().EffectiveAIConfig(ctx)
		if err != nil {
			return nil, errors.Join(errors.New("failed to resolve AI configuration"), err)
		}
		if effectiveAI != nil && !effectiveAI.AIEnabled {
			return nil, apperrors.NewAppError(apperrors.CodeUnprocessableEntity, apperrors.CategoryAPI, "AI analysis is not enabled on this instance")
		}
	}

	// Get AI service from registry
	aiSvc := r.Registry.AI()
	if aiSvc == nil {
		return nil, ErrAIServiceUnavailable
	}

	// Default values
	objType := TimelineTypeStatus
	if objectType != nil {
		objType = *objectType
	}
	forceAnalysis := false
	if force != nil {
		forceAnalysis = *force
	}

	// Queue for analysis
	result, err := aiSvc.QueueForAnalysis(ctx, &services_ai.QueueAnalysisCommand{
		ObjectID:   objectID,
		ObjectType: objType,
		Force:      forceAnalysis,
	})
	if err != nil {
		r.Logger.Error("failed to queue AI analysis",
			zap.String(adminRoleUser, username),
			zap.String("object_id", objectID),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to queue AI analysis"), err)
	}

	// Create request ID (not used in simplified response)
	_ = fmt.Sprintf("ai-req-%s-%d", objectID, time.Now().Unix())

	// Return request status
	message := "Analysis request queued successfully"
	if !result.Queued {
		message = "Analysis already exists and is recent"
	}
	return &model.AIAnalysisRequest{
		Message:       message,
		ObjectID:      objectID,
		EstimatedTime: "30s", // Typical analysis time
	}, nil
}

