// convertActivityPubObjectToModel converts an ActivityPub object to a GraphQL model object
func (r *Resolver) convertActorActivityObject(actor *activitypub.Actor) *model.Object {
	if actor == nil {
		return nil
	}

	actorCopy := *actor

	if actorCopy.Type == "" {
		actorCopy.Type = activitypub.PersonType
	}

	objectID := strings.TrimSpace(actorCopy.ID)
	if objectID == "" {
		objectID = strings.TrimSpace(actorCopy.URL)
	}
	if objectID == "" && strings.TrimSpace(actorCopy.PreferredUsername) != "" {
		objectID = fmt.Sprintf("actor:%s", strings.TrimSpace(actorCopy.PreferredUsername))
	}
	if objectID == "" {
		objectID = "actor:unknown"
	}

	createdAt := time.Now().UTC()
	switch {
	case actorCopy.CreatedAt != nil:
		createdAt = *actorCopy.CreatedAt
	case actorCopy.Published != nil:
		createdAt = *actorCopy.Published
	}

	updatedAt := createdAt
	switch {
	case actorCopy.Updated != nil:
		updatedAt = *actorCopy.Updated
	case actorCopy.LastStatusAt != nil:
		updatedAt = *actorCopy.LastStatusAt
	}

	content := strings.TrimSpace(actorCopy.Summary)
	contentMaps := make([]*model.ContentMap, 0, 1)
	if content != "" {
		contentMaps = append(contentMaps, &model.ContentMap{
			Language: "und",
			Content:  content,
		})
	}

	attachments := make([]*activitypub.Attachment, 0, 2)
	if actorCopy.Icon != nil && strings.TrimSpace(actorCopy.Icon.URL) != "" {
		icon := *actorCopy.Icon
		attachments = append(attachments, &activitypub.Attachment{
			Type:      icon.Type,
			MediaType: icon.MediaType,
			URL:       icon.URL,
			Name:      "avatar",
			Width:     icon.Width,
			Height:    icon.Height,
		})
	}
	if actorCopy.Image != nil && strings.TrimSpace(actorCopy.Image.URL) != "" {
		image := *actorCopy.Image
		attachments = append(attachments, &activitypub.Attachment{
			Type:      image.Type,
			MediaType: image.MediaType,
			URL:       image.URL,
			Name:      "header",
			Width:     image.Width,
			Height:    image.Height,
		})
	}

	actorPtr := actorCopy

	return &model.Object{
		ID:               objectID,
		Type:             model.ObjectTypePage,
		Actor:            &actorPtr,
		Content:          content,
		ContentMap:       contentMaps,
		InReplyTo:        nil,
		Visibility:       model.VisibilityPublic,
		Sensitive:        false,
		Attachments:      attachments,
		Tags:             []*activitypub.Tag{},
		Mentions:         []*model.Mention{},
		CreatedAt:        model.Time(createdAt),
		UpdatedAt:        model.Time(updatedAt),
		RepliesCount:     0,
		LikesCount:       0,
		SharesCount:      0,
		ContentHash:      contentHashForObjectID(objectID),
		EstimatedCost:    0,
		ModerationScore:  nil,
		CommunityNotes:   []*model.CommunityNote{},
		QuoteURL:         nil,
		Quoteable:        false,
		QuotePermissions: model.QuotePermissionNone,
		QuoteContext:     nil,
		QuoteCount:       0,
		Quotes: &model.QuoteConnection{
			Edges:      []*model.QuoteEdge{},
			PageInfo:   &model.PageInfo{HasNextPage: false, HasPreviousPage: false},
			TotalCount: 0,
		},
	}
}

func (r *Resolver) convertActivityPubObjectToModel(obj interface{}) *model.Object {
	if obj == nil {
		return nil
	}

	// Try to convert from storage models.Object
	storageObj, ok := obj.(*models.Object)
	if !ok {
		// Try BaseObject from activitypub
		baseObj, ok := obj.(*activitypub.BaseObject)
		if !ok {
			return nil
		}
		// Convert BaseObject to model.Object
		createdAt := time.Now()
		if baseObj.Published != nil {
			createdAt = *baseObj.Published
		}
		updatedAt := createdAt
		if baseObj.Updated != nil {
			updatedAt = *baseObj.Updated
		}

		return &model.Object{
			ID:          baseObj.ID,
			Type:        model.ObjectTypeNote, // Default to Note
			Content:     "",                   // BaseObject doesn't have content
			Sensitive:   false,
			CreatedAt:   model.Time(createdAt),
			UpdatedAt:   model.Time(updatedAt),
			Visibility:  model.VisibilityPublic, // Default visibility
			ContentHash: contentHashForObjectID(baseObj.ID),
		}
	}

	// Convert from storage Object
	createdAt := storageObj.CreatedAt
	updatedAt := storageObj.Updated

	modelObj := &model.Object{
		ID:          storageObj.ID,
		Type:        model.ObjectTypeNote, // Default to Note
		Content:     storageObj.Content,
		Sensitive:   storageObj.Sensitive,
		CreatedAt:   model.Time(createdAt),
		UpdatedAt:   model.Time(updatedAt),
		Visibility:  model.VisibilityPublic, // Default visibility
		ContentHash: contentHashForObjectID(storageObj.ID),
	}

	// Set type based on storage Object type
	switch storageObj.Type {
	case "Note":
		modelObj.Type = model.ObjectTypeNote
	case "Article":
		modelObj.Type = model.ObjectTypeArticle
	case "Image":
		modelObj.Type = model.ObjectTypeImage
	case "Video":
		modelObj.Type = model.ObjectTypeVideo
	case "Event":
		modelObj.Type = model.ObjectTypeEvent
	case "Place":
		modelObj.Type = model.ObjectTypeEvent // Map Place to Event as closest available
	case "Page":
		modelObj.Type = model.ObjectTypePage
	}

	// Set visibility based on audience
	if err := common.ValidateSliceNotEmpty("to", storageObj.To); err == nil {
		for _, to := range storageObj.To {
			if to == "https://www.w3.org/ns/activitystreams#Public" {
				modelObj.Visibility = model.VisibilityPublic
				break
			} else if strings.Contains(to, "/followers") {
				modelObj.Visibility = model.VisibilityFollowers
			}
		}
	}

	// Convert attachments if present
	modelObj.Attachments = []*activitypub.Attachment{}

	// Convert tags from JSON if available
	modelObj.Tags = []*activitypub.Tag{}
	if storageObj.TagJSON != "" {
		// Parse tags from JSON
		var tags []map[string]interface{}
		if err := json.Unmarshal([]byte(storageObj.TagJSON), &tags); err == nil {
			for _, tag := range tags {
				if name, ok := tag["name"].(string); ok {
					modelObj.Tags = append(modelObj.Tags, &activitypub.Tag{
						Type: "Hashtag",
						Name: name,
						Href: fmt.Sprintf("https://localhost/tags/%s", name),
					})
				}
			}
		}
	}

	// Set spoiler text if available
	if storageObj.Summary != "" {
		modelObj.SpoilerText = &storageObj.Summary
	}

	// Set counts - these would need to be fetched from separate queries in real implementation
	modelObj.RepliesCount = 0  // Would need to query replies
	modelObj.LikesCount = 0    // Would need to query likes
	modelObj.SharesCount = 0   // Would need to query shares
	modelObj.EstimatedCost = 0 // Could calculate from cost tracking

	return modelObj
}

